export const SENT = [{"at": 5, "end": 220, "text": "When a retired janitor in Vermont died in 2014, his will revealed he was worth almost $8 million."}, {"at": 221, "end": 368, "text": "Ronald Read grew up poor on a Vermont farm and was the first in his family to finish high school."}, {"at": 374, "end": 592, "text": "After the war, he pumped gas for about 25 years, then worked as a part-time janitor at JCPenney for 17 more."}, {"at": 598, "end": 817, "text": "He drove a second-hand Toyota Yaris, held his coat together with a safety pin, and chopped his own firewood into his nineties."}, {"at": 818, "end": 916, "text": "A stranger once paid for his meal, thinking he couldn't afford it."}, {"at": 920, "end": 1106, "text": "What nobody knew: for decades, he'd quietly bought shares in companies he understood, and held on to them."}, {"at": 1112, "end": 1211, "text": "When he died, he owned at least 95 stocks."}, {"at": 1217, "end": 1331, "text": "The certificates in his safe deposit box stood about 5 inches high."}, {"at": 1338, "end": 1376, "text": "Not every pick worked."}, {"at": 1383, "end": 1464, "text": "He held Lehman Brothers when it collapsed in 2008."}, {"at": 1469, "end": 1527, "text": "It was one stock out of dozens."}, {"at": 1534, "end": 1736, "text": "Then came the will: $4.8 million to the local hospital, $1.2 million to the library."}, {"at": 1737, "end": 1790, "text": "Twice its yearly budget."}, {"at": 1790, "end": 1983, "text": "In 2023, the hospital opened a new wing, partly paid for by his gift: the Ronald Read Pavilion."}, {"at": 1988, "end": 2034, "text": "He never earned a big salary."}, {"at": 2040, "end": 2093, "text": "He just gave his money time."}];
